// ---------------------------------------------------------------- fixed-size structs

fn words_to_bytes<const N: usize, const W: usize>(w: [u64; W]) -> [u8; N] {
    let mut out = [0u8; N];
    for (i, x) in w.iter().enumerate() {
        out[i * 8..i * 8 + 8].copy_from_slice(&x.to_le_bytes());
    }
    out
}

fn bytes_to_words<const N: usize, const W: usize>(b: &[u8; N]) -> [u64; W] {
    let mut out = [0u64; W];
    let (words, _) = b.as_chunks::<8>();
    for (x, w) in out.iter_mut().zip(words) {
        *x = u64::from_le_bytes(*w);
    }
    out
}

impl Key32 {
    pub fn from_bytes(b: &[u8; 32]) -> Self {
        let [b0, b1, b2, b3] = bytes_to_words::<32, 4>(b);
        Key32 { b0, b1, b2, b3 }
    }
    pub fn to_bytes(&self) -> [u8; 32] {
        words_to_bytes::<32, 4>([self.b0, self.b1, self.b2, self.b3])
    }
    pub fn is_zero(&self) -> bool {
        self.b0 == 0 && self.b1 == 0 && self.b2 == 0 && self.b3 == 0
    }
}

impl From<[u8; 32]> for Key32 {
    fn from(b: [u8; 32]) -> Self {
        Key32::from_bytes(&b)
    }
}
impl From<Key32> for [u8; 32] {
    fn from(k: Key32) -> Self {
        k.to_bytes()
    }
}

impl Sig64 {
    pub fn from_bytes(b: &[u8; 64]) -> Self {
        let [b0, b1, b2, b3, b4, b5, b6, b7] = bytes_to_words::<64, 8>(b);
        Sig64 {
            b0,
            b1,
            b2,
            b3,
            b4,
            b5,
            b6,
            b7,
        }
    }
    pub fn to_bytes(&self) -> [u8; 64] {
        words_to_bytes::<64, 8>([
            self.b0, self.b1, self.b2, self.b3, self.b4, self.b5, self.b6, self.b7,
        ])
    }
}

impl Id16 {
    pub fn from_bytes(b: &[u8; 16]) -> Self {
        let [b0, b1] = bytes_to_words::<16, 2>(b);
        Id16 { b0, b1 }
    }
    pub fn to_bytes(&self) -> [u8; 16] {
        words_to_bytes::<16, 2>([self.b0, self.b1])
    }
}

fn ip_words(ip: &IpAddr) -> (u8, u64, u64) {
    let mut b = [0u8; 16];
    let fam = match ip {
        IpAddr::V4(v4) => {
            b[..4].copy_from_slice(&v4.octets());
            4
        }
        IpAddr::V6(v6) => {
            b.copy_from_slice(&v6.octets());
            6
        }
    };
    let [a0, a1] = bytes_to_words::<16, 2>(&b);
    (fam, a0, a1)
}

fn words_ip(family: u8, a0: u64, a1: u64) -> Option<IpAddr> {
    let b = words_to_bytes::<16, 2>([a0, a1]);
    match family {
        4 => {
            if b[4..].iter().any(|x| *x != 0) {
                return None;
            }
            Some(IpAddr::V4(Ipv4Addr::new(b[0], b[1], b[2], b[3])))
        }
        6 => Some(IpAddr::V6(Ipv6Addr::from(b))),
        _ => None,
    }
}

impl IpAddress {
    pub fn from_ip(ip: IpAddr) -> Self {
        let (family, a0, a1) = ip_words(&ip);
        IpAddress { family, a0, a1 }
    }
    pub fn to_ip(&self) -> Option<IpAddr> {
        words_ip(self.family, self.a0, self.a1)
    }
}

impl SockAddr {
    pub fn from_sock(sa: SocketAddr) -> Self {
        let (family, a0, a1) = ip_words(&sa.ip());
        SockAddr {
            family,
            port: sa.port(),
            a0,
            a1,
        }
    }
    pub fn to_sock(&self) -> Option<SocketAddr> {
        words_ip(self.family, self.a0, self.a1).map(|ip| SocketAddr::new(ip, self.port))
    }
}

impl Cidr {
    /// Builds a CIDR; the caller is responsible for host bits (see `webjet-core`).
    pub fn new(ip: IpAddr, prefix: u8) -> Self {
        let (family, a0, a1) = ip_words(&ip);
        Cidr {
            family,
            prefix,
            a0,
            a1,
        }
    }
    pub fn addr(&self) -> Option<IpAddr> {
        words_ip(self.family, self.a0, self.a1)
    }
}

impl Transport {
    pub const ALL: [Transport; 3] = [Transport::KcpFecTls, Transport::AnyTls, Transport::TcpTls];
    pub fn name(&self) -> &'static str {
        match self {
            Transport::TcpTls => "tls",
            Transport::KcpFecTls => "kcp",
            Transport::AnyTls => "anytls",
        }
    }
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "tls" | "tcp" | "tcp+tls" => Some(Transport::TcpTls),
            "kcp" | "udp" | "udp+kcp+fec+tls" => Some(Transport::KcpFecTls),
            "anytls" | "tcp+anytls" => Some(Transport::AnyTls),
            _ => None,
        }
    }
    /// Tie-break order of §9.6: UDP+KCP+FEC, then TCP+AnyTLS, then TCP+TLS.
    pub fn tie_rank(&self) -> u8 {
        match self {
            Transport::KcpFecTls => 0,
            Transport::AnyTls => 1,
            Transport::TcpTls => 2,
        }
    }
}

