#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key32_roundtrip() {
        let mut b = [0u8; 32];
        for (i, x) in b.iter_mut().enumerate() {
            *x = i as u8;
        }
        let k = Key32::from_bytes(&b);
        assert_eq!(k.to_bytes(), b);
        let rec = NodeRecord {
            node_id: Some(k),
            name: Some("a".into()),
            version: 3,
            ..Default::default()
        };
        let bytes = rec.encode_bytes();
        let back = NodeRecord::decode_bytes(&bytes).unwrap();
        assert_eq!(back, rec);
        // The struct's in-buffer layout is exactly the 32 raw bytes.
        assert!(bytes.windows(32).any(|w| w == b));
    }

    #[test]
    fn sockaddr_roundtrip() {
        let sa: SocketAddr = "[2001:db8::1]:443".parse().unwrap();
        assert_eq!(SockAddr::from_sock(sa).to_sock(), Some(sa));
        let sa: SocketAddr = "10.1.2.3:80".parse().unwrap();
        assert_eq!(SockAddr::from_sock(sa).to_sock(), Some(sa));
    }

    #[test]
    fn garbage_rejected() {
        for len in 0..64 {
            let junk: Vec<u8> = (0..len).map(|i| (i * 37 + 11) as u8).collect();
            let _ = NodeRecord::decode_bytes(&junk);
            let _ = HopControl::decode_bytes(&junk);
        }
    }
}
